// pybytes.mjs — byte-array helpers mimicking Python bytes behaviour.

// Manual UTF-8 encoder: string -> array of byte values (0-255).
export function utf8Encode(str) {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    let cp = str.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < str.length) {
      const lo = str.charCodeAt(i + 1);
      if (lo >= 0xdc00 && lo <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
        i++;
      }
    }
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }
  return out;
}

// Reproduce CPython's repr() of a bytes object.
export function bytesRepr(bytes) {
  const hasSingle = bytes.includes(0x27);
  const hasDouble = bytes.includes(0x22);
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let s = 'b' + quote;
  for (const b of bytes) {
    if (b === 0x5c) s += '\\\\';
    else if (b === 0x09) s += '\\t';
    else if (b === 0x0a) s += '\\n';
    else if (b === 0x0d) s += '\\r';
    else if (b === quote.charCodeAt(0)) s += '\\' + quote;
    else if (b >= 0x20 && b <= 0x7e) s += String.fromCharCode(b);
    else s += '\\x' + b.toString(16).padStart(2, '0');
  }
  s += quote;
  return s;
}

// base58.mjs — pure-JS base58 (Bitcoin alphabet), matching PyPI base58.

export const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const ALPHABET_BYTES = Array.from(ALPHABET, (c) => c.charCodeAt(0));
const INDEXES = new Map(ALPHABET_BYTES.map((b, i) => [b, i]));

// bytes: number[] -> base58 ASCII codes (number[])
export function b58encode(bytes) {
  let zeros = 0;
  while (zeros < bytes.length && bytes[zeros] === 0) zeros++;

  let n = 0n;
  for (const b of bytes) n = (n << 8n) | BigInt(b);

  const digits = [];
  while (n > 0n) {
    const mod = Number(n % 58n);
    digits.push(ALPHABET_BYTES[mod]);
    n /= 58n;
  }

  const one = ALPHABET_BYTES[0];
  const out = new Array(zeros).fill(one);
  for (let i = digits.length - 1; i >= 0; i--) out.push(digits[i]);
  return out;
}

// str: base58 string -> decoded bytes (number[])
export function b58decode(str) {
  let n = 0n;
  for (const ch of str) {
    const code = ch.charCodeAt(0);
    const v = INDEXES.get(code);
    if (v === undefined) {
      throw new Error(`Invalid character ${JSON.stringify(ch)}`);
    }
    n = n * 58n + BigInt(v);
  }

  const bytes = [];
  while (n > 0n) {
    bytes.push(Number(n & 0xffn));
    n >>= 8n;
  }
  bytes.reverse();

  let zeros = 0;
  while (zeros < str.length && str[zeros] === '1') zeros++;
  return new Array(zeros).fill(0).concat(bytes);
}

// n: non-negative integer (number or BigInt) -> base58 ASCII codes.
// PyPI: b58encode_int(0) == b'1'; no leading-zero padding.
export function b58encodeInt(n) {
  let v = BigInt(n);
  if (v === 0n) return [ALPHABET_BYTES[0]];
  const digits = [];
  while (v > 0n) {
    digits.push(ALPHABET_BYTES[Number(v % 58n)]);
    v /= 58n;
  }
  return digits.reverse();
}

// str: base58 string -> integer (JS number).
export function b58decodeInt(str) {
  let n = 0;
  for (const ch of str) {
    const v = INDEXES.get(ch.charCodeAt(0));
    if (v === undefined) {
      throw new Error(`Invalid character ${JSON.stringify(ch)}`);
    }
    n = n * 58 + v;
  }
  return n;
}

// base58check.mjs — double-SHA256 4-byte checksum variants, matching
// PyPI base58's b58encode_check / b58decode_check.

import { createHash } from 'node:crypto';
import { b58encode, b58decode } from './base58.mjs';

function sha256(bytes) {
  const hex = createHash('sha256')
    .update(String.fromCharCode(...bytes), 'latin1')
    .digest('hex');
  const out = [];
  for (let i = 0; i < hex.length; i += 2) {
    out.push(parseInt(hex.slice(i, i + 2), 16));
  }
  return out;
}

function checksum(bytes) {
  return sha256(sha256(bytes)).slice(0, 4);
}

// bytes: number[] -> base58check ASCII codes (number[])
export function b58encodeCheck(bytes) {
  return b58encode(bytes.concat(checksum(bytes)));
}

// bytesOrStr: base58check string or its ASCII codes -> payload bytes (number[])
export function b58decodeCheck(bytesOrStr) {
  const str = typeof bytesOrStr === 'string'
    ? bytesOrStr
    : String.fromCharCode(...bytesOrStr);
  const decoded = b58decode(str);
  if (decoded.length < 4) {
    throw new Error('Input too short for checksum');
  }
  const payload = decoded.slice(0, -4);
  const ck = decoded.slice(-4);
  const expected = checksum(payload);
  for (let i = 0; i < 4; i++) {
    if (ck[i] !== expected[i]) {
      throw new Error('Invalid checksum');
    }
  }
  return payload;
}

// args.mjs — minimal manual process.argv parser mirroring argparse's
// `--name value` form for the flags used by test20.

const STRING_FLAGS = ['a', 'b', 'c', 'd', 'e'];
const INT_FLAGS = ['f', 'g'];

export function parseArgs(argv = process.argv.slice(2)) {
  const values = {};
  for (let i = 0; i < argv.length; i++) {
    const tok = argv[i];
    if (!tok.startsWith('--')) {
      throw new Error(`unrecognized argument: ${tok}`);
    }
    const name = tok.slice(2);
    if (!STRING_FLAGS.includes(name) && !INT_FLAGS.includes(name)) {
      throw new Error(`unrecognized argument: --${name}`);
    }
    if (i + 1 >= argv.length) {
      throw new Error(`argument --${name}: expected one argument`);
    }
    const raw = argv[++i];
    if (INT_FLAGS.includes(name)) {
      const n = Number.parseInt(raw, 10);
      if (Number.isNaN(n) || String(n) !== raw.trim()) {
        throw new Error(`argument --${name}: invalid int value: ${raw}`);
      }
      values[name] = n;
    } else {
      values[name] = raw;
    }
  }
  for (const name of STRING_FLAGS.concat(INT_FLAGS)) {
    if (!(name in values)) {
      throw new Error(`the following arguments are required: --${name}`);
    }
  }
  return values;
}

// test20.mjs — JS port of test20.py (PyPI base58 call sequence).

import { parseArgs } from './args.mjs';
import { utf8Encode, bytesRepr } from './pybytes.mjs';
import { b58encode, b58decode, b58encodeInt, b58decodeInt } from './base58.mjs';
import { b58encodeCheck, b58decodeCheck } from './base58check.mjs';

const args = parseArgs();

const enc1 = b58encode(utf8Encode(args.a));
const dec1 = b58decode(args.b);
const encCheck1 = b58encodeCheck(utf8Encode(args.c));
const decCheck1 = b58decodeCheck(encCheck1);
const encInt1 = b58encodeInt(args.f);
const decInt1 = b58decodeInt(String.fromCharCode(...encInt1));
const enc2 = b58encode(utf8Encode(args.d));
const dec2 = b58decode(args.e);
const encInt2 = b58encodeInt(args.g);
const encCheck2 = b58encodeCheck(dec1);
const decCheck2 = b58decodeCheck(encCheck2);
const enc3 = b58encode(decCheck2);

